defmodule Vault.Ledger.Fold do
  def initial(account_id), do: %Vault.Ledger.AccountState{account_id: account_id}

  def apply_event(%Vault.Ledger.AccountState{account_id: aid} = state, %Vault.Ledger.Event{} = event) do
    # 1. account_id mismatch
    if aid != nil and event.account_id != aid, do: {:error, {:account_mismatch, aid, event.account_id}}
    # 2. version gap
    else if event.version != state.version + 1, do: {:error, {:version_gap, state.version + 1, event.version}}
    # 3. unknown event type
    else do
      type = case event.payload do
        %Ash.Union{type: t} when t in [:account_opened, :deposited, :withdrawn, :frozen, :unfrozen] -> t
        _ -> :unknown
      end
      if type == :unknown, do: {:error, {:unknown_event_type, extract_raw_type(event.payload)}}
      else do
        apply_rules(state, event, type)
      end
    end
  end

  defp extract_raw_type(%Ash.Union{type: t}), do: t
  defp extract_raw_type(_), do: nil

  defp apply_rules(state, event, type) do
    payload = event.payload.value
    case {type, state.status} do
      {:account_opened, :absent} -> 
        {:ok, %{state | owner: payload.owner, balance_cents: payload.opening_balance_cents, status: :open, version: event.version, last_event_type: :account_opened, last_recorded_at: event.recorded_at}}
      {:account_opened, _} -> {:error, :already_open}
      {:deposited, :open} -> 
        {:ok, %{state | balance_cents: state.balance_cents + payload.amount_cents, deposit_count: state.deposit_count + 1, version: event.version, last_event_type: :deposited, last_recorded_at: event.recorded_at}}
      {:deposited, :absent} -> {:error, :account_absent}
      {:deposited, :frozen} -> {:error, :account_frozen}
      {:withdrawn, :open} ->
        new_bal = state.balance_cents - payload.amount_cents
        if new_bal < 0, do: {:error, :insufficient_funds},
        else: {:ok, %{state | balance_cents: new_bal, withdrawal_count: state.withdrawal_count + 1, version: event.version, last_event_type: :withdrawn, last_recorded_at: event.recorded_at}}
      {:withdrawn, :absent} -> {:error, :account_absent}
      {:withdrawn, :frozen} -> {:error, :account_frozen}
      {:frozen, :open} ->
        {:ok, %{state | status: :frozen, version: event.version, last_event_type: :frozen, last_recorded_at: event.recorded_at}}
      {:frozen, _} -> {:error, :not_open}
      {:unfrozen, :frozen} ->
        {:ok, %{state | status: :open, version: event.version, last_event_type: :unfrozen, last_recorded_at: event.recorded_at}}
      {:unfrozen, _} -> {:error, :not_frozen}
      _ -> {:error, {:unhandled, type, state.status}}
    end
  end

  def replay(state, events) do
    # check ordering by sequence
    bad = Enum.find_index(Enum.chunk_every(events, 2, 1, :discard), fn [a, b] -> b.sequence <= a.sequence end)
    if bad, do: {:error, {:out_of_order, bad + 1}},
    else: Enum.reduce_while(events, {:ok, state}, fn e, {:ok, s} -> case apply_event(s, e) do
      {:ok, s2} -> {:cont, {:ok, s2}}
      {:error, r} -> {:halt, {:error, r}}
    end end)
  end
end

